SET NAMES utf8mb4;
SET time_zone = "+00:00";
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";

CREATE TABLE `bookings` (
  `id` int UNSIGNED NOT NULL,
  `guest_company_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `car_id` int UNSIGNED DEFAULT NULL,
  `custom_car_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `secondary_car_id` int UNSIGNED DEFAULT NULL,
  `driver_id` int UNSIGNED DEFAULT NULL,
  `custom_driver_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `operator_id` int UNSIGNED DEFAULT NULL,
  `operator_name` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `even_odd` enum('Even','Odd') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `status` enum('Pending','Confirm','Completed','Cancelled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Pending',
  `remark` text COLLATE utf8mb4_general_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `customers` (
  `id` int UNSIGNED NOT NULL,
  `company_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `guest_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_person` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_phone` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_email` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `customer_address` text COLLATE utf8mb4_general_ci,
  `off_day` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `service_hour` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `customer_status` enum('Active','Inactive') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Active',
  `remark` text COLLATE utf8mb4_general_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `bookings`
  ADD PRIMARY KEY (`id`),
  ADD KEY `fk_bookings_car` (`car_id`),
  ADD KEY `fk_bookings_driver` (`driver_id`),
  ADD KEY `idx_bookings_operator_id` (`operator_id`),
  ADD KEY `idx_bookings_secondary_car_id` (`secondary_car_id`);

ALTER TABLE `customers`
  ADD PRIMARY KEY (`id`);

ALTER TABLE `bookings`
  MODIFY `id` int UNSIGNED NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=270;

ALTER TABLE `customers`
  MODIFY `id` int UNSIGNED NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=18;

ALTER TABLE `bookings`
  ADD CONSTRAINT `fk_bookings_car` FOREIGN KEY (`car_id`) REFERENCES `cars` (`id`) ON UPDATE CASCADE,
  ADD CONSTRAINT `fk_bookings_driver` FOREIGN KEY (`driver_id`) REFERENCES `drivers` (`id`) ON UPDATE CASCADE,
  ADD CONSTRAINT `fk_bookings_operator` FOREIGN KEY (`operator_id`) REFERENCES `operators` (`id`) ON UPDATE CASCADE,
  ADD CONSTRAINT `fk_bookings_secondary_car` FOREIGN KEY (`secondary_car_id`) REFERENCES `cars` (`id`) ON DELETE SET NULL ON UPDATE CASCADE;
